@extends('layout') @section('title','Messagerie') @section('subtitle','Un échange confidentiel au sein de votre espace.') @section('content')<div class="two-columns"><section class="panel form-panel"><h2>Mes échanges</h2>@forelse($messages as $m)<article class="message {{ $m->sender_id===auth()->id() ? 'outgoing' : '' }}"><div class="message-meta"><strong>{{ $m->sender->name }} → {{ $m->recipient->name }}</strong><small>{{ $m->created_at->format('d/m/Y H:i') }}</small></div><p class="prewrap">{{ $m->body }}</p></article>@empty<p class="empty">Aucun message pour le moment.</p>@endforelse{{ $messages->links('partials.pagination') }}</section><section class="panel form-panel"><h2>Nouveau message</h2><form method="post" action="/messagerie">@csrf<label>Destinataire<select name="recipient_id" required><option value="">Choisir un destinataire</option>@foreach($recipients as $u)<option value="{{ $u->id }}">{{ $u->name }} · {{ $u->role }}</option>@endforeach</select></label><label>Votre message<textarea name="body" rows="8" required maxlength="10000">{{ old('body') }}</textarea></label><button class="btn primary">Envoyer le message</button></form></section></div>@endsection